#[test]
fn environment_and_hierarchical_aliases_keep_cargo_precedence() {
    let f = Fixture::new();
    let project = f.project("package -suffix");
    let install = array(&["install", "--path", project.to_str().unwrap()]);
    // The lower-priority array contributes its command, the local one its path.
    std::fs::create_dir_all(f.root.join(".cargo")).unwrap();
    std::fs::write(f.root.join(".cargo/config.toml"), "[alias]\ni=['install']\n").unwrap();
    f.config(&format!("[alias]\ni={}\n", array(&["--path", project.to_str().unwrap()])));
    for shim in [false, true] {
        rejected(f.command(shim).arg("i").env("REJECT_METADATA", "1").output().unwrap());
        succeeded(f.command(shim).arg("i").env("CARGO_ALIAS_I", "probe").output().unwrap());
        rejected(f.command(shim).args(["env-install", "--path"]).arg(&project)
            .env("CARGO_ALIAS_ENV_INSTALL", "install").env("REJECT_METADATA", "1").output().unwrap());
    }
    // Legacy config wins over config.toml, including for built-in shorthand.
